arguments.command:
cd /workspace/task && python3 - <<'EOF'
import re
src = open('scratch/report.md', encoding='utf-8').read()
lines = src.split('\n')
start = None
for i, l in enumerate(lines):
    if l.strip() == '## 风险':
        start = i + 1
        break
if start is None:
    raise SystemExit('section not found')
end = len(lines)
for j in range(start, len(lines)):
    if re.match(r'^##\s', lines[j]):
        end = j
        break
body = '\n'.join(lines[start:end]).strip()
open('scratch/risk.txt', 'w', encoding='utf-8').write(body + '\n')
EOF
echo "=== risk.txt:"; cat -A scratch/risk.txt; echo "=== md5 after:"; md5sum scratch/report.md
